SELECT id, display_name, employee_no, email, avatar_url, role, status, merged_into_user_id,
       created_at, updated_at
FROM app_user u


        EXISTS (
            SELECT 1 FROM user_identity ui
            WHERE ui.user_id = u.id AND ui.provider = #{provider}
        )


ORDER BY id
LIMIT #{limit} OFFSET #{offset}

SELECT count(*)
FROM app_user u


        EXISTS (
            SELECT 1 FROM user_identity ui
            WHERE ui.user_id = u.id AND ui.provider = #{provider}
        )
